from fastapi import FastAPI
from fastapi.testclient import TestClient
from pydantic import BaseModel, computed_field

app = FastAPI(separate_input_output_schemas=False)

class Item(BaseModel):
    name: str

    @computed_field
    @property
    def description(self) -> str:
        return f"Description of {self.name}"

@app.get("/item", response_model=Item)
def read_item():
    return Item(name="test")

client = TestClient(app)

def test_openapi():
    openapi_schema = client.openapi()
    # Check if 'description' is in the Item schema
    item_schema = openapi_schema["components"]["schemas"]["Item"]
    assert "description" in item_schema["properties"], f"Computed field 'description' missing from Item schema. Properties: {item_schema['properties']}"

if __name__ == "__main__":
    try:
        test_openapi()
        print("Test passed!")
    except AssertionError as e:
        print(f"Test failed: {e}")
    except Exception as e:
        print(f"An error occurred: {e}")

